-- Temas: trayecto resuelto por la UNIQUE (nivel, anio_o_carrera, materia);
-- orden 1..n dentro de cada materia/trayecto.
INSERT INTO matching.temas (trayecto_id, nombre, descripcion, orden)
SELECT t.id, v.nombre, v.descripcion, v.orden::int
FROM (VALUES
  -- (nivel, anio_o_carrera, materia, orden, nombre, descripcion)
('primario', '1°', 'Ciencias Naturales', '1', 'Los seres vivos', 'Características de los seres vivos: nacen, crecen, se reproducen y mueren; diferencias con los objetos que no tienen vida.'),
  ('primario', '1°', 'Ciencias Naturales', '2', 'Los animales', 'Animales domésticos y silvestres: cómo se desplazan, qué comen y dónde viven; animales del entorno cercano.'),
  ('primario', '1°', 'Ciencias Naturales', '3', 'Las plantas', 'Partes de la planta: raíz, tallo, hojas, flor y fruto; qué necesitan las plantas para vivir y crecer.'),
  ('primario', '1°', 'Ciencias Naturales', '4', 'El cuerpo humano', 'Partes del cuerpo: cabeza, tronco y extremidades; el conocimiento y el cuidado del propio cuerpo.'),
  ('primario', '1°', 'Ciencias Naturales', '5', 'Los cinco sentidos', 'Los sentidos y los órganos que los perciben; observar y conocer el entorno a través de los sentidos.'),
  ('primario', '1°', 'Ciencias Naturales', '6', 'Los alimentos', 'Alimentos de origen animal y vegetal; la importancia de comer variado y sano para crecer.'),
  ('primario', '1°', 'Ciencias Naturales', '7', 'El agua', 'El agua en la vida cotidiana: sus usos, el agua potable y el cuidado de este recurso.'),
  ('primario', '1°', 'Ciencias Naturales', '8', 'Los materiales', 'Materiales de los objetos: madera, vidrio, metal, plástico y tela; propiedades observables de cada uno.'),
  ('primario', '1°', 'Ciencias Naturales', '9', 'La higiene y la salud', 'Higiene corporal, lavado de manos y cuidado del cuerpo para prevenir enfermedades y mantenerse sano.'),
  ('primario', '1°', 'Ciencias Sociales', '1', 'La escuela', 'La escuela como espacio común: normas de convivencia, tareas compartidas y responsabilidades del grupo.'),
  ('primario', '1°', 'Ciencias Sociales', '2', 'La familia', 'Distintos tipos de familias; los vínculos entre sus integrantes y las tareas que se comparten en el hogar.'),
  ('primario', '1°', 'Ciencias Sociales', '3', 'El barrio y la localidad', 'El barrio: calles, comercios, plazas y lugares de referencia; los distintos espacios de la vida cercana.'),
  ('primario', '1°', 'Ciencias Sociales', '4', 'El calendario y las estaciones', 'El calendario, las estaciones del año y la organización del tiempo en la vida social y escolar.'),
  ('primario', '1°', 'Ciencias Sociales', '5', 'Los oficios y trabajos', 'Oficios de la comunidad: quiénes trabajan en el barrio y para qué sirve la tarea que realizan.'),
  ('primario', '1°', 'Ciencias Sociales', '6', 'La vivienda', 'Distintos tipos de vivienda, sus materiales y espacios; modos de habitar en diferentes lugares y épocas.'),
  ('primario', '1°', 'Ciencias Sociales', '7', 'La historia personal y familiar', 'La historia personal y familiar: cambios a lo largo del tiempo observados en fotos, objetos y testimonios.'),
  ('primario', '1°', 'Ciencias Sociales', '8', 'Conmemoraciones y efemérides', 'Las efemérides que se conmemoran en la escuela: qué recordamos, por qué y de qué manera lo celebramos.'),
  ('primario', '1°', 'Educación Artística', '1', 'El color', 'Colores primarios: rojo, amarillo y azul; identificación y aplicación en el dibujo y la pintura.'),
  ('primario', '1°', 'Educación Artística', '2', 'El dibujo y la línea', 'Líneas rectas y curvas, distintos trazos y el dibujo expresivo; el garabato y el dibujo con intención.'),
  ('primario', '1°', 'Educación Artística', '3', 'Texturas y formas', 'Exploración de texturas (áspero, suave, rugoso) y de formas del entorno; estampado y marcado.'),
  ('primario', '1°', 'Educación Artística', '4', 'La figura humana', 'El dibujo de la figura humana: partes del cuerpo y proporciones simples; la representación de las personas.'),
  ('primario', '1°', 'Educación Artística', '5', 'El ritmo y la percusión', 'El ritmo y el pulso: percusión corporal (palmas, pies) y juegos rítmicos; el tempo lento y rápido.'),
  ('primario', '1°', 'Educación Artística', '6', 'La voz y el canto', 'La voz cantada y hablada; canciones infantiles y juegos vocales; el cuidado de la voz.'),
  ('primario', '1°', 'Educación Artística', '7', 'Los sonidos del entorno', 'Sonidos de la naturaleza y de la ciudad: reconocimiento, imitación y clasificación (fuerte-suave, agudo-grave).'),
  ('primario', '1°', 'Educación Artística', '8', 'La expresión corporal', 'La expresión corporal y el movimiento: juegos de dramatización, gestos y desplazamientos con el cuerpo.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '1', 'Normas de convivencia', 'Normas del aula y de la escuela: acuerdos, respeto y responsabilidades compartidas en el grupo.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '2', 'Los derechos del niño', 'Primeras nociones de derechos: todos los niños tienen derecho a jugar, a la escuela y a la salud.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '3', 'El respeto y el buen trato', 'El buen trato hacia los otros: saludos, escucha atenta y cuidado en el trato cotidiano.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '4', 'Las emociones', 'Reconocimiento y expresión de emociones: alegría, enojo, miedo y tristeza; cómo nombrar lo que sentimos.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '5', 'El diálogo', 'El diálogo como modo de resolver diferencias: hablar, escuchar y ponerse de acuerdo.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '6', 'La identidad personal', 'El nombre, la propia historia y la pertenencia a una familia y a una comunidad; sentirse parte.'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '7', 'El cuidado del propio cuerpo', 'El cuidado de sí mismo: higiene, alimentación y reconocimiento de situaciones de incomodidad; pedir ayuda (ESI).'),
  ('primario', '1°', 'Formación Ética y Ciudadana', '8', 'La cooperación', 'Trabajar y jugar en grupo: compartir, ayudar y colaborar con los otros.'),
  ('primario', '1°', 'Inglés', '1', 'Greetings and introductions', 'Saludos y presentaciones: hello, hi, good morning; preguntar y responder el propio nombre (What''s your name?).'),
  ('primario', '1°', 'Inglés', '2', 'The alphabet', 'El alfabeto: letras y sonidos; deletrear palabras simples (spelling) con juegos y canciones.'),
  ('primario', '1°', 'Inglés', '3', 'Numbers', 'Los números del 1 al 10: contar objetos, reconocer numerales y responder How many?'),
  ('primario', '1°', 'Inglés', '4', 'Colors', 'Los colores: nombrar e identificar colores básicos (red, blue, yellow, green) en objetos cotidianos.'),
  ('primario', '1°', 'Inglés', '5', 'Classroom objects', 'Objetos del aula: pencil, book, desk, chair; instrucciones básicas (sit down, open your book, listen).'),
  ('primario', '1°', 'Inglés', '6', 'Family members', 'La familia: mother, father, brother, sister, baby; responder Who is this? con vocabulario familiar.'),
  ('primario', '1°', 'Inglés', '7', 'Animals', 'Animales domésticos y salvajes: dog, cat, bird; descripciones simples (a dog is small) con canciones.'),
  ('primario', '1°', 'Inglés', '8', 'Body parts', 'Partes del cuerpo: head, eyes, nose, mouth, hands, feet; juegos, canciones y presentación de sí mismo.'),
  ('primario', '1°', 'Lengua', '1', 'Alfabeto', 'Reconocimiento de las letras del alfabeto en mayúsculas y minúsculas; orden alfabético; asociación entre letras y sonidos.'),
  ('primario', '1°', 'Lengua', '2', 'Conciencia fonológica', 'Sonidos iniciales y finales de las palabras; segmentación en sílabas; juegos con rimas y sonidos.'),
  ('primario', '1°', 'Lengua', '3', 'Lectura inicial', 'Lectura de palabras y oraciones breves con apoyo de imágenes; sílabas directas, inversas y complejas (ma-me, al-el, pra-pre).'),
  ('primario', '1°', 'Lengua', '4', 'Escritura de palabras', 'Escritura de palabras de uso frecuente; copia y dictado; orientación de la escritura y separación entre palabras.'),
  ('primario', '1°', 'Lengua', '5', 'Cuentos tradicionales', 'Escucha y lectura de cuentos clásicos; personajes, escenarios y secuencia de hechos; la narración oral de cuentos conocidos.'),
  ('primario', '1°', 'Lengua', '6', 'Rimas y canciones', 'Poesías, rimas y canciones infantiles; el juego sonoro con la lengua y la memorización de versos breves.'),
  ('primario', '1°', 'Lengua', '7', 'Comprensión lectora', 'Comprensión de textos breves: qué sucede, quiénes intervienen y dónde; responder preguntas simples sobre lo leído.'),
  ('primario', '1°', 'Lengua', '8', 'La narración', 'Estructura del cuento: inicio, desarrollo y final; narrar oralmente hechos personales y secuencias de situaciones cotidianas.'),
  ('primario', '1°', 'Matemática', '1', 'Números', 'Escritura, lectura y orden de los números hasta el 100; serie numérica, anterior y posterior; comparación (mayor, menor, igual).'),
  ('primario', '1°', 'Matemática', '2', 'Sumas y restas', 'Sumas y restas de números de una y dos cifras, con y sin canjes; tablas de sumar y estrategias de cálculo mental.'),
  ('primario', '1°', 'Matemática', '3', 'Figuras geométricas', 'Reconocimiento y descripción de triángulo, cuadrado, rectángulo y círculo; lados y vértices; composición con otras figuras.'),
  ('primario', '1°', 'Matemática', '4', 'Cuerpos geométricos', 'Exploración de cubo, prisma, cilindro y esfera; sus caras y su presencia en objetos cotidianos.'),
  ('primario', '1°', 'Matemática', '5', 'Medidas de longitud', 'Comparaciones directas de longitudes (largo y corto); uso de la regla y el centímetro; el metro.'),
  ('primario', '1°', 'Matemática', '6', 'El calendario y el tiempo', 'Lectura del calendario, días de la semana y meses; organización del tiempo: ayer, hoy y mañana; antes y después.'),
  ('primario', '1°', 'Matemática', '7', 'Medidas de capacidad y peso', 'Comparaciones de capacidad (lleno, vacío) y de peso (liviano, pesado); el litro y el kilogramo.'),
  ('primario', '1°', 'Matemática', '8', 'Problemas sencillos', 'Resolución de problemas simples de sumar y restar con un solo paso, a partir de situaciones cotidianas.'),
  ('primario', '1°', 'Matemática', '9', 'Organización de datos', 'Registros y tablas sencillas: conteo, encuestas y pictogramas para organizar información de la vida cotidiana.'),
  ('primario', '1°', 'Tecnología', '1', 'Los objetos tecnológicos', 'Objetos creados por las personas para satisfacer necesidades: su función, sus partes y sus usos.'),
  ('primario', '1°', 'Tecnología', '2', 'Las herramientas', 'Herramientas de uso escolar y doméstico: para qué sirven, su cuidado y su uso seguro.'),
  ('primario', '1°', 'Tecnología', '3', 'Los materiales de los objetos', 'Materiales de los objetos cotidianos: madera, cartón, plástico y metal; la elección del material según el uso.'),
  ('primario', '1°', 'Tecnología', '4', 'Los juguetes', 'Juguetes y su funcionamiento: objetos que se mueven, suenan o encajan; exploración y desarmado simple.'),
  ('primario', '1°', 'Tecnología', '5', 'El proceso de fabricación', 'Cómo se hacen los objetos: pasos de diseñar, conseguir materiales, construir y probar; ejemplos conocidos.'),
  ('primario', '1°', 'Tecnología', '6', 'La organización del trabajo', 'Trabajo en equipo y organización de tareas: planificar los pasos y los turnos para construir un objeto.'),
  ('primario', '1°', 'Tecnología', '7', 'La computadora', 'Uso de la computadora en la escuela: encender, cuidar el equipo y usos básicos en el aula.'),
  ('primario', '1°', 'Tecnología', '8', 'La seguridad en el uso de objetos', 'Prevención de accidentes: el uso correcto y seguro de herramientas y dispositivos cotidianos.'),
  ('primario', '2°', 'Ciencias Naturales', '1', 'El ciclo de vida de los seres vivos', 'El ciclo de vida de animales y plantas: nacen, crecen, se desarrollan y mueren; los cambios en cada etapa.'),
  ('primario', '2°', 'Ciencias Naturales', '2', 'Animales y su ambiente', 'Animales del entorno y sus ambientes: cubierta del cuerpo, alimentación (herbívoros, carnívoros, omnívoros) y desplazamiento.'),
  ('primario', '2°', 'Ciencias Naturales', '3', 'Las plantas y su crecimiento', 'Germinación y crecimiento de las plantas; qué necesitan para vivir; la huerta y las plantas del entorno.'),
  ('primario', '2°', 'Ciencias Naturales', '4', 'El agua en la naturaleza', 'Estados del agua: sólido, líquido y gaseoso; el agua en el ambiente: ríos, lagos, lluvia y nubes.'),
  ('primario', '2°', 'Ciencias Naturales', '5', 'El aire y el viento', 'El aire: su existencia, sus propiedades y su importancia para los seres vivos; el viento y sus efectos.'),
  ('primario', '2°', 'Ciencias Naturales', '6', 'Los materiales y sus cambios', 'Transformaciones de los materiales: mezclas sencillas, calor y frío; cambios que se pueden observar a diario.'),
  ('primario', '2°', 'Ciencias Naturales', '7', 'La alimentación saludable', 'Los alimentos y sus grupos; desayuno, merienda y comidas saludables; hábitos de alimentación variada.'),
  ('primario', '2°', 'Ciencias Naturales', '8', 'El suelo y los seres vivos', 'El suelo: qué es, seres vivos que lo habitan y su importancia para las plantas y los animales.'),
  ('primario', '2°', 'Ciencias Sociales', '1', 'La localidad', 'La localidad: límites, puntos de referencia, barrios y centros urbanos; el plano de la localidad.'),
  ('primario', '2°', 'Ciencias Sociales', '2', 'Los medios de transporte', 'Medios de transporte terrestres, aéreos y acuáticos; su evolución y su función en la comunidad.'),
  ('primario', '2°', 'Ciencias Sociales', '3', 'Instituciones de la comunidad', 'Instituciones públicas: escuela, hospital, comisaría y municipio; la función de cada una en la comunidad.'),
  ('primario', '2°', 'Ciencias Sociales', '4', 'El trabajo', 'Trabajos urbanos y rurales: quiénes trabajan y qué producen; por qué el trabajo organiza la vida social.'),
  ('primario', '2°', 'Ciencias Sociales', '5', 'Historia de la localidad', 'La historia de la localidad: cómo era antes y cómo es ahora; los testimonios orales como fuente histórica.'),
  ('primario', '2°', 'Ciencias Sociales', '6', 'El campo y la ciudad', 'El campo y la ciudad: actividades, paisajes y modos de vida propios de cada espacio.'),
  ('primario', '2°', 'Ciencias Sociales', '7', 'Pueblos originarios', 'Pueblos originarios de la Argentina: vida cotidiana, costumbres, vivienda y relación con la naturaleza.'),
  ('primario', '2°', 'Ciencias Sociales', '8', 'Los símbolos patrios', 'Símbolos nacionales: bandera, escudo e himno; las fechas patrias y el significado de las conmemoraciones.'),
  ('primario', '2°', 'Educación Artística', '1', 'Los colores secundarios', 'Mezclas para obtener colores secundarios: naranja, verde y violeta; matices y variaciones de color.'),
  ('primario', '2°', 'Educación Artística', '2', 'El modelado', 'Modelado con masa y arcilla: volúmenes, formas tridimensionales y texturas con las manos.'),
  ('primario', '2°', 'Educación Artística', '3', 'El collage', 'El collage y la composición: recorte, pegado y combinación de materiales de distinta textura.'),
  ('primario', '2°', 'Educación Artística', '4', 'Los instrumentos de percusión', 'Instrumentos de percusión: triángulo, tambor y pandero; su sonido y el acompañamiento rítmico de canciones.'),
  ('primario', '2°', 'Educación Artística', '5', 'El canto colectivo', 'El canto en grupo y las canciones tradicionales infantiles; el respeto por la propia voz y la de los otros.'),
  ('primario', '2°', 'Educación Artística', '6', 'La danza y el movimiento', 'Danzas simples: ritmos, desplazamientos y expresión con el cuerpo; juegos de danza en parejas y en rondas.'),
  ('primario', '2°', 'Educación Artística', '7', 'La observación de obras', 'Observación de pinturas y esculturas: qué se ve, qué colores y formas tiene, y qué expresa cada obra.'),
  ('primario', '2°', 'Educación Artística', '8', 'El juego dramático', 'El juego dramático: representar personajes con la voz, los gestos y los disfraces; la improvisación.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '1', 'Los derechos del niño', 'Los derechos del niño según la Convención: jugar, estudiar y tener una familia; a quién recurrir para que se cumplan.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '2', 'Las reglas de los juegos', 'Los acuerdos y las reglas en juegos y actividades; la importancia de conocerlas y cumplirlas.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '3', 'La igualdad', 'La igualdad entre las personas: varones y mujeres pueden hacer las mismas cosas; respeto por todas las personas.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '4', 'La solidaridad', 'Ser solidario: ayudar a otros, dar y recibir; situaciones de colaboración en la escuela y el barrio.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '5', 'El respeto por las diferencias', 'El respeto por las diferencias: otras costumbres, lenguas y formas de vivir; conocer y valorar la diversidad.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '6', 'La participación', 'Participar en la escuela: opinar, proponer y decidir en grupo; las asambleas de aula.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '7', 'La responsabilidad', 'La responsabilidad personal: tareas, compromisos y cumplimiento de lo acordado en el grupo.'),
  ('primario', '2°', 'Formación Ética y Ciudadana', '8', 'El cuidado de sí y del otro', 'Prevención del daño: cuidado del cuerpo, contacto seguro y pedir ayuda a un adulto de confianza (ESI).'),
  ('primario', '2°', 'Inglés', '1', 'Numbers up to 100', 'Números hasta el 100: contar, la edad (I am seven) y los números de teléfono; decenas y unidades.'),
  ('primario', '2°', 'Inglés', '2', 'Days of the week and months', 'Días de la semana y meses del año: Today is..., My birthday is in...; el calendario.'),
  ('primario', '2°', 'Inglés', '3', 'The weather', 'El tiempo atmosférico: sunny, rainy, cloudy, windy; What''s the weather like? y respuestas simples.'),
  ('primario', '2°', 'Inglés', '4', 'Food and drinks', 'Alimentos y bebidas: food names; expresar gustos con I like / I don''t like.'),
  ('primario', '2°', 'Inglés', '5', 'Verb to be', 'El verbo to be (am, is, are): afirmativo, negativo y preguntas simples (I am, you are, he is).'),
  ('primario', '2°', 'Inglés', '6', 'Toys and possessions', 'Juguetes y objetos personales; adjetivos posesivos (my, your); What is it? It''s a... (ball, doll, car).'),
  ('primario', '2°', 'Inglés', '7', 'Classroom instructions', 'Instrucciones y consignas del aula: stand up, sit down, listen, repeat, write, color; respuesta a órdenes.'),
  ('primario', '2°', 'Inglés', '8', 'Places in town', 'Lugares del pueblo y la escuela: school, park, shop, house; preposiciones de lugar in, on, under; descripción de dónde está algo.'),
  ('primario', '2°', 'Lengua', '1', 'La oración', 'La oración como unidad de sentido; orden de las palabras; uso de mayúscula inicial y punto final.'),
  ('primario', '2°', 'Lengua', '2', 'Sustantivos', 'Sustantivos propios y comunes; singular y plural; masculino y femenino; reconocimiento de sustantivos en textos.'),
  ('primario', '2°', 'Lengua', '3', 'Adjetivos', 'Adjetivos que describen personas, animales y objetos; concordancia de género y número con el sustantivo.'),
  ('primario', '2°', 'Lengua', '4', 'El verbo', 'Acciones en presente, pasado y futuro; reconocimiento de verbos en oraciones de uso cotidiano.'),
  ('primario', '2°', 'Lengua', '5', 'Ortografía', 'Mayúsculas al iniciar textos y en nombres propios; mb y mp; ca-co-cu y ce-ci; escritura de palabras frecuentes.'),
  ('primario', '2°', 'Lengua', '6', 'Comprensión lectora', 'Comprensión de cuentos y textos breves: personajes, lugar y secuencia de hechos; anticipación y verificación de lo leído.'),
  ('primario', '2°', 'Lengua', '7', 'Cuentos y narraciones', 'Cuentos tradicionales y de hadas: leer, narrar y reordenar hechos; el diálogo y la voz de los personajes.'),
  ('primario', '2°', 'Lengua', '8', 'Textos descriptivos', 'Descripción de personas, animales y objetos en forma oral y escrita; características y detalles sensoriales.'),
  ('primario', '2°', 'Lengua', '9', 'Sinónimos y antónimos', 'Palabras de significado semejante y opuesto; ampliación del vocabulario en textos y juegos de palabras.'),
  ('primario', '2°', 'Matemática', '1', 'Números hasta 1.000', 'Lectura, escritura, orden y valor posicional hasta el número 1.000; unidades, decenas y centenas; desarmado de números.'),
  ('primario', '2°', 'Matemática', '2', 'Sumas y restas con canjes', 'Sumas y restas de números de hasta tres cifras con canjes; verificación con la operación inversa.'),
  ('primario', '2°', 'Matemática', '3', 'La multiplicación', 'Inicio de la multiplicación como suma reiterada; la tabla pitagórica y los dobles; multiplicar por 2, 5 y 10.'),
  ('primario', '2°', 'Matemática', '4', 'Figuras planas y ángulos', 'Triángulo, cuadrado, rectángulo y círculo: lados y vértices; identificación de ángulos rectos en las figuras.'),
  ('primario', '2°', 'Matemática', '5', 'Medidas de longitud', 'El metro y el centímetro; medir con la regla y la cinta métrica; estimación de longitudes.'),
  ('primario', '2°', 'Matemática', '6', 'Medidas de capacidad y peso', 'El litro y el kilogramo; comparar y medir capacidades y pesos con unidades convencionales.'),
  ('primario', '2°', 'Matemática', '7', 'El reloj', 'Lectura de la hora en relojes de aguja y digitales; horas, medias horas y cuartos de hora.'),
  ('primario', '2°', 'Matemática', '8', 'Tablas y gráficos', 'Interpretación y construcción de tablas, pictogramas y gráficos de barras con datos recolectados.'),
  ('primario', '2°', 'Matemática', '9', 'Problemas de dos pasos', 'Resolución de problemas de suma, resta y multiplicación que requieren más de un paso; respuesta con la pregunta del problema.'),
  ('primario', '2°', 'Tecnología', '1', 'La evolución de los objetos', 'Objetos que nos rodean y su evolución: juguetes y objetos de ayer y de hoy; cambios de materiales y diseño.'),
  ('primario', '2°', 'Tecnología', '2', 'Las máquinas en la vida cotidiana', 'Las máquinas que nos rodean: qué hacen y cómo facilitan las tareas (bicicleta, licuadora, lavadora).'),
  ('primario', '2°', 'Tecnología', '3', 'Las herramientas manuales', 'Herramientas manuales de la escuela: uso con cuidado, mantenimiento y normas de seguridad básicas.'),
  ('primario', '2°', 'Tecnología', '4', 'Los materiales y sus propiedades', 'Propiedades de los materiales: resistencia, flexibilidad y transparencia; cómo elegir material al fabricar.'),
  ('primario', '2°', 'Tecnología', '5', 'Construir un objeto', 'El proceso de construcción de un objeto simple: diseño, armado y prueba; un proyecto en el aula.'),
  ('primario', '2°', 'Tecnología', '6', 'Las tecnologías del hogar', 'Objetos y máquinas de la casa: su función y el consumo responsable de energía y agua.'),
  ('primario', '2°', 'Tecnología', '7', 'La huerta y las técnicas de cultivo', 'La huerta escolar: preparar la tierra, sembrar y cuidar; técnicas simples de cultivo y de riego.'),
  ('primario', '2°', 'Tecnología', '8', 'La computadora y sus usos', 'La computadora y sus usos: programas sencillos, dibujo y juegos educativos; cuidados del equipo.'),
  ('primario', '3°', 'Ciencias Naturales', '1', 'Las funciones vitales de los seres vivos', 'Funciones de nutrición, relación y reproducción en los seres vivos; clasificación básica en animales, plantas y hongos.'),
  ('primario', '3°', 'Ciencias Naturales', '2', 'Las plantas: crecimiento y reproducción', 'Crecimiento y reproducción de las plantas: semillas, flores y frutos; esquejes y otras formas de multiplicación.'),
  ('primario', '3°', 'Ciencias Naturales', '3', 'Las cadenas alimentarias', 'Cadenas alimentarias: productores, consumidores y descomponedores; las relaciones entre los seres vivos.'),
  ('primario', '3°', 'Ciencias Naturales', '4', 'El ciclo del agua', 'El ciclo del agua en la naturaleza: evaporación, condensación y precipitación; el agua que viaja por el ambiente.'),
  ('primario', '3°', 'Ciencias Naturales', '5', 'Cambios de estado de la materia', 'Los estados de la materia: sólido, líquido y gaseoso; cambios de estado como la fusión, la evaporación y la condensación.'),
  ('primario', '3°', 'Ciencias Naturales', '6', 'Materiales naturales y artificiales', 'Materiales naturales y artificiales; propiedades como dureza, flexibilidad y transparencia; sus usos.'),
  ('primario', '3°', 'Ciencias Naturales', '7', 'La alimentación y la nutrición', 'Los alimentos y la nutrición: grupos de alimentos y nutrientes; la importancia del agua y del equilibrio en la dieta.'),
  ('primario', '3°', 'Ciencias Naturales', '8', 'Los hongos y los microorganismos', 'Hongos que vemos (champiñones, mohos) y microorganismos: qué son y qué papel cumplen en la naturaleza y en los alimentos.'),
  ('primario', '3°', 'Ciencias Sociales', '1', 'El campo y la ciudad', 'El campo y la ciudad: paisajes, actividades productivas y la relación entre ambos espacios.'),
  ('primario', '3°', 'Ciencias Sociales', '2', 'Los circuitos productivos', 'Circuitos productivos: origen, producción, elaboración y comercialización de bienes (leche, pan, papel).'),
  ('primario', '3°', 'Ciencias Sociales', '3', 'Los recursos naturales y el trabajo', 'Los recursos naturales y su aprovechamiento por el trabajo humano; el uso responsable de los recursos.'),
  ('primario', '3°', 'Ciencias Sociales', '4', 'El trabajo rural', 'Trabajos del campo: cosechas, cría de animales y actividades agrícolas; las producciones regionales de la Argentina.'),
  ('primario', '3°', 'Ciencias Sociales', '5', 'El comercio y el dinero', 'El comercio: vendedores, compradores, mercado y dinero en los intercambios; la compra y venta cotidiana.'),
  ('primario', '3°', 'Ciencias Sociales', '6', 'Mapas y orientación', 'Planos y mapas sencillos: referencias, puntos cardinales y orientación en el espacio; leer el plano del aula y del barrio.'),
  ('primario', '3°', 'Ciencias Sociales', '7', 'Las comunicaciones', 'Los medios de comunicación y su evolución: carta, teléfono, radio, televisión e internet; su papel en la sociedad.'),
  ('primario', '3°', 'Ciencias Sociales', '8', 'La vida social a través del tiempo', 'Cómo vivían las personas en otras épocas: costumbres, formas de trabajo y vida cotidiana de familias de otros tiempos.'),
  ('primario', '3°', 'Educación Artística', '1', 'La composición visual', 'La composición en la imagen: organización de figura y fondo, equilibrio y elementos en el plano.'),
  ('primario', '3°', 'Educación Artística', '2', 'La mezcla de colores', 'Mezclas y gamas cromáticas: colores cálidos y fríos, claros y oscuros; gradaciones de un mismo color.'),
  ('primario', '3°', 'Educación Artística', '3', 'La música folclórica argentina', 'La música folclórica argentina: ritmos como la chacarera y la zamba; instrumentos y el canto popular.'),
  ('primario', '3°', 'Educación Artística', '4', 'El sonido y sus cualidades', 'Cualidades del sonido: agudo y grave, largo y corto, fuerte y suave; el timbre de los instrumentos.'),
  ('primario', '3°', 'Educación Artística', '5', 'La historieta', 'La historieta: viñetas, globos de diálogo, onomatopeyas y la secuencia narrativa de la historia.'),
  ('primario', '3°', 'Educación Artística', '6', 'La danza folclórica', 'Danzas tradicionales y folclóricas: pasos básicos, ritmos y el trabajo en pareja y en grupo.'),
  ('primario', '3°', 'Educación Artística', '7', 'El teatro escolar', 'El teatro: personajes, conflicto, diálogos y una puesta en escena breve; el trabajo de los actores.'),
  ('primario', '3°', 'Educación Artística', '8', 'La naturaleza en el arte', 'El paisaje y la naturaleza en el arte: dibujo y pintura del entorno; artistas que pintan paisajes.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '1', 'Derechos y responsabilidades', 'Derechos y responsabilidades en la escuela y la comunidad; el cuidado de los bienes de todos.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '2', 'Resolución pacífica de conflictos', 'Conflictos cotidianos y modos pacíficos de resolverlos: diálogo, mediación de pares y acuerdos.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '3', 'La diversidad cultural', 'La diversidad cultural en la Argentina: aportes de los pueblos originarios y de las migraciones; el respeto como valor.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '4', 'La autoestima y el autoconocimiento', 'El conocimiento de sí mismo: gustos, capacidades y la valoración del propio cuerpo; la confianza en uno mismo (ESI).'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '5', 'Libertad y responsabilidad', 'La libertad y la responsabilidad: elegir y dar cuenta de lo elegido; límites necesarios para convivir.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '6', 'La vida democrática en la escuela', 'Democracia en la escuela: elección de delegados, asamblea y reglas elaboradas en común.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '7', 'La honestidad y la convivencia', 'Valores para convivir: honestidad, lealtad y justicia; cómo se ponen en juego en la vida escolar.'),
  ('primario', '3°', 'Formación Ética y Ciudadana', '8', 'El cuidado de los espacios comunes', 'El respeto por los espacios compartidos: aulas, patios y plazas; la responsabilidad sobre lo de todos.'),
  ('primario', '3°', 'Inglés', '1', 'Present simple (routines)', 'Presente simple: hábitos y rutinas (I get up, I go to school); la tercera persona con -s; preguntas y negaciones.'),
  ('primario', '3°', 'Inglés', '2', 'There is / There are', 'There is / There are para describir lo que hay: afirmativo, negativo y preguntas; uso con singular y plural.'),
  ('primario', '3°', 'Inglés', '3', 'Have got', 'Have got / Has got para posesión y apariencia (I have got blue eyes, He has got a dog); formas completa y corta.'),
  ('primario', '3°', 'Inglés', '4', 'Describing people and animals', 'Descripción de personas y animales: tall, short, big, small, long hair, fat; estructura de oraciones descriptivas.'),
  ('primario', '3°', 'Inglés', '5', 'Telling the time', 'La hora: o''clock y half past; What time is it? y la relación con la rutina diaria.'),
  ('primario', '3°', 'Inglés', '6', 'Can and can''t', 'Can / Can''t para habilidades y permiso: I can swim, Can you...?; respuestas cortas yes, I can / no, I can''t.'),
  ('primario', '3°', 'Inglés', '7', 'Wh-questions', 'Preguntas con what, where, when, who, why, how many; formación y respuesta de preguntas abiertas.'),
  ('primario', '3°', 'Inglés', '8', 'Like + -ing', 'Expresar gustos con like, love, hate + verbo con -ing (I like playing football); hablar de hobbies e intereses.'),
  ('primario', '3°', 'Lengua', '1', 'Sustantivos', 'Sustantivos propios, comunes, individuales y colectivos; género, número y su función en la oración.'),
  ('primario', '3°', 'Lengua', '2', 'Tiempos verbales', 'Verbos en presente, pasado y futuro; regularidades en las terminaciones; uso en la narración de hechos.'),
  ('primario', '3°', 'Lengua', '3', 'Textos narrativos', 'Cuentos, fábulas y leyendas: estructura, personajes y enseñanza; la narración oral de historias propias y ajenas.'),
  ('primario', '3°', 'Lengua', '4', 'Ortografía', 'Uso de b y v; c, s y z; g y j; la h muda; escritura correcta de palabras de uso frecuente.'),
  ('primario', '3°', 'Lengua', '5', 'Sinónimos y antónimos', 'Reconocimiento y uso de sinónimos y antónimos para ampliar el vocabulario y evitar repeticiones.'),
  ('primario', '3°', 'Lengua', '6', 'Comprensión lectora', 'Lectura comprensiva de textos narrativos y expositivos breves: ideas principales, personajes y propósito del texto.'),
  ('primario', '3°', 'Lengua', '7', 'El texto descriptivo', 'Descripción de personas, lugares y objetos con oraciones organizadas; el orden en la descripción escrita.'),
  ('primario', '3°', 'Lengua', '8', 'Poesía', 'Poesías, rimas y versos; recursos sonoros del lenguaje y la lectura expresiva de poemas.'),
  ('primario', '3°', 'Matemática', '1', 'Números hasta 10.000', 'Lectura, escritura y orden de números hasta 10.000; valor posicional con unidades de mil; comparación y aproximación.'),
  ('primario', '3°', 'Matemática', '2', 'Multiplicación por una cifra', 'Multiplicación por una cifra con algoritmo; tablas de multiplicar; propiedades conmutativa y asociativa; problemas.'),
  ('primario', '3°', 'Matemática', '3', 'La división', 'División exacta e inexacta; cociente y resto; relación entre división y multiplicación; división por una cifra.'),
  ('primario', '3°', 'Matemática', '4', 'Fracciones', 'Nociones de fracción: medios, tercios y cuartos; representación gráfica; fracciones equivalentes sencillas.'),
  ('primario', '3°', 'Matemática', '5', 'Figuras y perímetro', 'Figuras planas y su perímetro; cálculo del perímetro sumando los lados; comparación de figuras con igual perímetro.'),
  ('primario', '3°', 'Matemática', '6', 'Ángulos y giros', 'Ángulos rectos y no rectos; identificación en figuras y en el entorno; giros de cuarto y media vuelta.'),
  ('primario', '3°', 'Matemática', '7', 'Medidas', 'El metro, el litro y el gramo; equivalencias simples entre unidades convencionales de longitud, capacidad y peso.'),
  ('primario', '3°', 'Matemática', '8', 'Datos y azar', 'Recolección de datos, tablas y gráficos de barras; situaciones de azar: posibles, seguras e imposibles.'),
  ('primario', '3°', 'Tecnología', '1', 'Las máquinas simples', 'Máquinas simples: palanca, polea y plano inclinado; cómo facilitan el esfuerzo en las tareas.'),
  ('primario', '3°', 'Tecnología', '2', 'Los mecanismos', 'Mecanismos que transmiten movimiento: rueda, engranajes y manivela; sus aplicaciones en objetos y máquinas.'),
