  ('secundario', '3°', 'Geografía', '5', 'Circuitos productivos', 'Los circuitos productivos regionales: actores, eslabones y las economías regionales argentinas.'),
  ('secundario', '3°', 'Geografía', '6', 'Ambiente y desarrollo sostenible', 'Los problemas ambientales, la noción de desarrollo sustentable y las políticas ambientales.'),
  ('secundario', '3°', 'Geografía', '7', 'Argentina en el mundo', 'La inserción de Argentina en el comercio internacional, el Mercosur y los procesos de integración regional.'),
