  ('secundario', '6°', 'Filosofía', '3', 'Filosofía moderna', 'El racionalismo de Descartes, el empirismo de Hume y el problema del conocimiento.'),
  ('secundario', '6°', 'Filosofía', '4', 'Ilustración y Kant', 'La filosofía de Kant, el imperativo categórico y el proyecto de la Ilustración.'),
  ('secundario', '6°', 'Filosofía', '5', 'Marx y la crítica social', 'La crítica de Marx al capitalismo: alienación, materialismo histórico y praxis.'),
